import subprocess, tempfile, os, sys, json
S = os.path.join(tempfile.mkdtemp(), "c.sqlite")
def c(*a): return subprocess.run([sys.executable, "_tools/coord.py", "--store", S, *a], capture_output=True, text=True)
T = {"none": ["claimed"], "claimed": ["working", "released"], "working": ["returned", "failed", "blocked"],
     "blocked": ["working", "returned", "failed"], "returned": ["staging", "landing", "working", "released"],
     "failed": ["working", "released"], "staging": ["returned"], "landing": ["landed", "refused"],
     "refused": ["working", "landing", "released"], "landed": [], "released": []}
ALL = [s for s in T if s != "none"]
def path(dst):
    seen, todo = {"none": []}, ["none"]
    while todo:
        s = todo.pop(0)
        for n in T[s]:
            if n not in seen:
                seen[n] = seen[s] + [n]; todo.append(n)
    return seen[dst]
def val(k):
    try:
        v = json.loads(c("get", k).stdout)
    except ValueError:
        return None
    return (str(v.get("value")), v.get("revision")) if v.get("ok") else ("none", 0)
def count():
    try:
        return len(json.loads(c("wait", "--since", "0", "--timeout", "0").stdout)["events"])
    except ValueError:
        return -1
n = [0]
def key(src):
    n[0] += 1; k = "run/ST-%08d" % n[0]
    for s in path(src):
        c("transition", k, "--to", s)
    return k
bad = []
for src in T:
    k = key(src)
    for dst in ALL:
        if dst in T[src]:
            k2 = key(src); r1 = val(k2); e1 = count(); r = c("transition", k2, "--to", dst); r2 = val(k2)
            if r.returncode != 0 or r1 is None or r2 is None or dst not in r2[0] or r2[1] <= r1[1] or count() != e1 + 1:
                bad.append(("allowed move failed", src, dst))
        else:
            r1 = val(k); e1 = count(); r = c("transition", k, "--to", dst); text = r.stdout + r.stderr
            if r.returncode != 1 or val(k) != r1 or count() != e1 or (src != "none" and src not in text) or any(t not in text for t in T[src]):
                bad.append(("refused move wrong", src, dst, r.returncode))
